package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.BeanProperty;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitable;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonStringFormatVisitor;
import com.fasterxml.jackson.databind.jsonschema.SchemaAware;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.ser.BeanSerializer;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.JsonSerializer;
import com.fasterxml.jackson.databind.ser.SerializerProvider;
import com.fasterxml.jackson.databind.ser.impl.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.ser.std.JsonValueSerializer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.LinkedHashSet;
import java.util.Set;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class JsonValueSerializer_acceptJsonFormatVisitor_TriageGen1Test {

    private JsonValueSerializer serializer;
    private JsonFormatVisitorWrapper visitor;
    private JavaType typeHint;
    private SerializerProvider provider;
    private AnnotatedMethod annotatedMethod;
    private BeanProperty property;

    // Using a subclass to expose protected methods and access private fields via reflection if necessary,
    // but here we will attempt to mock/stub the behavior through the constructor-like setup or mocking.
    // Since we cannot easily call the constructor with private fields, we use Mockito to spy or mock.

    @Before
    public void setUp() {
        visitor = mock(JsonFormatVisitorWrapper.class);
        typeHint = mock(JavaType.class);
        provider = mock(SerializerProvider.class);
        annotatedMethod = mock(AnnotatedMethod.class);
        property = mock(BeanProperty.class);

        // We use a spy to allow overriding the protected method _acceptJsonFormatVisitorForEnum
        serializer = spy(new JsonValueSerializer(null, null, false));
    }

    /**
     * Helper to inject fields into the serializer via reflection because they are private/protected
     */
    private void injectFields(JsonValueSerializer target, AnnotatedMethod method, JsonSerializer<Object> ser, BeanProperty prop) throws Exception {
        java.lang.reflect.Field methodField = JsonValueSerializer.class.getDeclaredField("_accessorMethod");
        methodField.setAccessible(true);
        methodField.set(target, method);

        java.lang.reflect.Field serField = JsonValueSerializer.class.getDeclaredField("_valueSerializer");
        serField.setAccessible(true);
        serField.set(target, ser);

        java.lang.reflect.Field propField = JsonValueSerializer.class.getDeclaredField("_property");
        propField.setAccessible(true);
        propField.set(target, prop);
    }

    @Test
    public void testEnumDeclaringClass_ReturnsTrue() throws Exception {
        enum TestEnum { VALUE }
        when(annotatedMethod.getDeclaringClass()).thenReturn(TestEnum.class);
        when(annotatedMethod.getType()).thenReturn(typeHint);
        doReturn(true).when(serializer)._acceptJsonFormatVisitorForEnum(any(), any(), eq(TestEnum.class));

        injectFields(serializer, annotatedMethod, null, property);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(serializer)._acceptJsonFormatVisitorForEnum(visitor, typeHint, TestEnum.class);
        verifyNoMoreInteractions(visitor);
    }

    @Test
    public void testEnumDeclaringClass_ReturnsFalse() throws Exception {
        enum TestEnum { VALUE }
        when(annotatedMethod.getDeclaringClass()).thenReturn(TestEnum.class);
        when(annotatedMethod.getType()).thenReturn(typeHint);
        doReturn(false).when(serializer)._acceptJsonFormatVisitorForEnum(any(), any(), eq(TestEnum.class));

        // Setup for the fallback (ser is null, so we find it)
        JsonSerializer<Object> fallbackSer = mock(JsonSerializer.class);
        when(provider.findTypedValueSerializer(eq(typeHint), eq(false), eq(property))).thenReturn(fallbackSer);

        // We need to mock the visitor to return provider
        when(visitor.getProvider()).thenReturn(provider);

        injectFields(serializer, annotatedMethod, null, property);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(serializer)._acceptJsonFormatVisitorForEnum(visitor, typeHint, TestEnum.class);
        verify(fallbackSer).acceptJsonFormatVisitor(visitor, null);
    }

    @Test
    public void testNonEnumDeclaringClass_WithExistingSerializer() throws Exception {
        when(annotatedMethod.getDeclaringClass()).thenReturn(String.class);
        when(annotatedMethod.getType()).thenReturn(typeHint);

        JsonSerializer<Object> existingSer = mock(JsonSerializer.class);
        injectFields(serializer, annotatedMethod, existingSer, property);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(existingSer).acceptJsonFormatVisitor(visitor, null);
    }

    @Test
    public void testNonEnumDeclaringClass_WithNullSerializer_FindsSerializer() throws Exception {
        when(annotatedMethod.getDeclaringClass()).thenReturn(String.class);
        when(annotatedMethod.getType()).thenReturn(typeHint);

        JsonSerializer<Object> foundSer = mock(JsonSerializer.class);
        when(visitor.getProvider()).thenReturn(provider);
        when(provider.findTypedValueSerializer(typeHint, false, property)).thenReturn(foundSer);

        injectFields(serializer, annotatedMethod, null, property);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(foundSer).acceptJsonFormatVisitor(visitor, null);
    }

    @Test
    public void testNonEnumDeclaringClass_WithNullSerializer_CannotFindSerializer() throws Exception {
        when(annotatedMethod.getDeclaringClass()).thenReturn(String.class);
        when(annotatedMethod.getType()).thenReturn(typeHint);

        when(visitor.getProvider()).thenReturn(provider);
        when(provider.findTypedValueSerializer(typeHint, false, property)).thenReturn(null);

        injectFields(serializer, annotatedMethod, null, property);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(visitor).expectAnyFormat(typeHint);
    }

    @Test
    public void testNullDeclaringClass() throws Exception {
        when(annotatedMethod.getDeclaringClass()).thenReturn(null);
        when(annotatedMethod.getType()).thenReturn(typeHint);

        JsonSerializer<Object> existingSer = mock(JsonSerializer.class);
        injectFields(serializer, annotatedMethod, existingSer, property);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(existingSer).acceptJsonFormatVisitor(visitor, null);
    }
}
